#ifndef CXCOMPOSITESTEP_MQH
#define CXCOMPOSITESTEP_MQH

#include "..\..\Interfaces\IXStep.mqh"
#include "..\..\Interfaces\IXTask.mqh"
#include "..\..\Interfaces\CXMacros.mqh"
#include <Arrays\ArrayObj.mqh>

/**
 * @class CXCompositeStep
 * @brief 여러 개의 IXTask(마이크로 태스크)를 조립하여 순차 실행하는 복합 시퀀스 스텝
 */
class CXCompositeStep : public IXStep {
private:
    string      m_name;
    CArrayObj   m_tasks;
    int         m_currentTaskIndex; // [Refinement 1] Resume Pointer
    bool        m_hasConditionFunc;

public:
    CXCompositeStep(string name) : m_name(name), m_currentTaskIndex(0), m_hasConditionFunc(false) {}
    virtual ~CXCompositeStep() {
        m_tasks.Clear();
    }

    virtual string Name() override { return m_name; }

    /**
     * @brief 실행할 태스크를 체인에 추가합니다.
     */
    CXCompositeStep* AddTask(IXTask* task) {
        if(IS_VALID(task)) {
            m_tasks.Add(task);
        }
        return GetPointer(this);
    }

    /**
     * @brief 기본적으로 true를 반환하며, 태스크 내부 로직에서 조건을 필터링합니다.
     */
    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        return true; 
    }

    /**
     * @brief 등록된 태스크들을 순차적으로 실행
     */
    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        for(int i = m_currentTaskIndex; i < m_tasks.Total(); i++) {
            IXTask* task = dynamic_cast<IXTask*>(m_tasks.At(i));
            if(IS_VALID(task)) {
                // [v9.9.2] 타임아웃 검증
                if(task.IsTimedOut()) {
                    XP_LOG_ERROR(xp, StringFormat("[%s] Task Timeout. Moving to SESSION_ERROR.", task.Name()));
                    m_currentTaskIndex = 0; // Reset
                    return SESSION_ERROR;
                }

                int res = task.Execute(xp, ctx);

                // 1. 특정 상태로 전이 지시 시 즉시 반환 (성공/상태변경)
                if(res >= 0) {
                    task.ResetRetry(); 
                    m_currentTaskIndex = 0; // Reset for next state
                    return res;
                }
                // 2. 실행 중지(Break) 지시 시 남은 태스크 무시하고 현재 상태 유지
                else if(res == TASK_BREAK) {
                    m_currentTaskIndex = 0; // Restart chain on next process call
                    return STATE_UNCHANGED;
                }
                // 3. 비차단 대기(Yield) 시 인덱스 유지하고 다음 틱 대기
                else if(res == TASK_YIELD) {
                    m_currentTaskIndex = i; // [Refinement 1] Save current position
                    task.IncrementRetry();
                    if(task.IsMaxRetriesExceeded()) {
                        XP_LOG_ERROR(xp, StringFormat("[%s] Max Retries Exceeded. Moving to SESSION_ERROR.", task.Name()));
                        m_currentTaskIndex = 0;
                        return SESSION_ERROR;
                    }
                    return STATE_UNCHANGED;
                }
                // 4. TASK_CONTINUE(-1) 시 다음 태스크로 진행
                else if(res == TASK_CONTINUE) {
                    task.ResetRetry(); 
                    m_currentTaskIndex = i + 1; // Move to next
                }
            }
        }

        m_currentTaskIndex = 0; // 체인 완주 시 리셋
        return STATE_UNCHANGED; 
    }

    virtual void OnEnter(ICXContext* ctx) override {
        m_currentTaskIndex = 0; // 진입 시 항상 0부터 시작
        XP_LOG_DEBUG(NULL, StringFormat("[%s] Composite Step Entered (%d tasks)", m_name, m_tasks.Total()));
    }

    virtual void OnExit(ICXContext* ctx) override {
        m_currentTaskIndex = 0; 
        XP_LOG_DEBUG(NULL, StringFormat("[%s] Composite Step Exited", m_name));
    }
};

#endif

#ifndef IXTASK_MQH
#define IXTASK_MQH

#include <Object.mqh>
#include "ICXParam.mqh"
#include "ICXContext.mqh"

// Task 실행 결과 제어 상수
#define TASK_CONTINUE   -1  // 다음 태스크로 진행
#define TASK_BREAK      -2  // 현재 상태 유지하고 체인 실행 중단 (이번 틱 종료)
#define TASK_YIELD      -3  // 비차단 대기: 현재 상태를 유지하되 다음 틱에서 재시도

/**
 * @interface IXTask
 * @brief 시퀀스 스텝(Step) 내부에서 단일 책임을 수행하는 원자적 태스크 인터페이스
 * [v9.9.2] Hyper-Atomization을 위한 상태 제어 상수 및 프로퍼티 확장
 */
class IXTask : public CObject {
protected:
    int m_maxRetries;
    int m_retryCount;
    int m_timeoutSeconds;
    datetime m_startTime;

public:
    IXTask() : m_maxRetries(0), m_retryCount(0), m_timeoutSeconds(0), m_startTime(0) {}
    virtual ~IXTask() {}

    virtual string Name() = 0;

    /**
     * @brief 태스크 로직 실행
     * @return 양수(상태 코드): 즉시 해당 상태로 시퀀스 전이 발생
     *         TASK_CONTINUE: 다음 태스크로 흐름을 넘김
     *         TASK_BREAK: 태스크 체인 실행을 멈추고 현재 상태를 유지함
     *         TASK_YIELD: 비차단 대기 (다음 틱에서 해당 태스크부터 다시 시작)
     */
    virtual int Execute(ICXParam* xp, ICXContext* ctx) = 0;

    //-- 속성 관리
    void SetMaxRetries(int r) { m_maxRetries = r; }
    void SetTimeout(int s) { m_timeoutSeconds = s; }

    int  GetRetryCount() const { return m_retryCount; }
    void IncrementRetry() { m_retryCount++; }
    void ResetRetry() { m_retryCount = 0; m_startTime = 0; }

    bool IsTimedOut() {
        if(m_timeoutSeconds <= 0) return false;
        if(m_startTime == 0) m_startTime = TimeCurrent();
        bool timedOut = (TimeCurrent() - m_startTime >= m_timeoutSeconds);
        if(timedOut) ResetRetry(); // 타임아웃 발생 시 상태 초기화 (재시도 루프 종료용)
        return timedOut;
    }

    bool IsMaxRetriesExceeded() const {
        return (m_maxRetries > 0 && m_retryCount >= m_maxRetries);
    }
};

#endif

#ifndef CX_TASK_ENTRY_P_FINALIZE_MQH
#define CX_TASK_ENTRY_P_FINALIZE_MQH

#include "..\..\..\Interfaces\IXTask.mqh"
#include "..\..\..\Interfaces\CXMacros.mqh"
#include "..\..\..\Interfaces\IRepository.mqh"
#include "..\..\..\Infra\CXMessageProvider.mqh"

/**
 * @class CXTaskEntry_P_Finalize
 * @brief [Persistence] DB 상태 최종 확정
 */
class CXTaskEntry_P_Finalize : public IXTask {
public:
    virtual string Name() override { return "Entry_P_Finalize"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IRepository* repo = CX_GET_OBJ(ctx, "repo", IRepository);
        if(IS_INVALID(sig) || IS_INVALID(repo)) return TASK_BREAK;

        int targetStatus = (sig.GetType() == ORDER_MARKET) ? XE_EXECUTED : XE_PENDING_PLACED;
        string msg = (targetStatus == XE_EXECUTED) ? "Entry Executed (Market)" : "Entry Pending Placed (Trailing)";
        int nextSessionState = (targetStatus == XE_EXECUTED) ? SESSION_ACTIVE : STATE_ENTRY_TRAILING;

        XP_LOG_TRACE(xp, StringFormat("[ENTRY-P-FINALIZE] Committing Final State: %d (%s)...", targetStatus, msg));

        CXMessageProvider::UpdateStatus(sig, targetStatus, msg);
        if(repo.UpdateStatus(sig)) {
            XP_LOG_OK(xp, StringFormat("[ENTRY-P-FINALIZE] SUCCESS: DB Updated. Moving Session to %d.", nextSessionState));
            return nextSessionState;
        }

        XP_LOG_WARN(xp, "[ENTRY-P-FINALIZE] YIELD: DB Update Delayed. Retrying...");
        return TASK_YIELD;
    }
};

#endif

#ifndef CX_TASK_EXIT_R_ORDER_MQH
#define CX_TASK_EXIT_R_ORDER_MQH

#include "..\..\..\Interfaces\IXTask.mqh"
#include "..\..\..\Interfaces\CXMacros.mqh"
#include "..\..\..\Interfaces\IXExitManager.mqh"

/**
 * @class CXTaskExit_R_Order
 * @brief [Request] 브로커에 청산(Close/Cancel) 주문 송신
 */
class CXTaskExit_R_Order : public IXTask {
public:
    virtual string Name() override { return "Exit_R_Order"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        IXExitManager* exitMgr = CX_GET_OBJ(ctx, "exit_mgr", IXExitManager);
