        string info = StringFormat("Sequence Assembly Complete: [Name:%s] [Nodes:%d] [States:{%s}]", 
                                   seq.GetSequenceName(), seq.GetNodeCount(), seq.GetStateSummary());
        XP_LOG_INFO(GetPointer(xp), info);
    }
};

