                .AddTask(new CXTaskExit_R_Order()); // Returns STATE_LIQUIDATING_TRANSIT

        seq.From(SESSION_LIQUIDATING).Execute(exitStep_L)
           .OnSuccess(STATE_LIQUIDATING_TRANSIT)
           .OnFail(SESSION_ERROR)
           .Timeout(300)
